import { describe, expect, it } from "vitest";
import {
  PLAN_CARD_FEATURES,
  PLAN_COMPARISON_ROWS,
  PLAN_FEATURES,
} from "@/lib/plan-features";

describe("complete plan feature catalog", () => {
  it("publishes the role and shortcut limits for both plans", () => {
    expect(PLAN_COMPARISON_ROWS).toContainEqual([
      "Contact job roles",
      "Any role",
      "Any role",
    ]);
    expect(PLAN_COMPARISON_ROWS).toContainEqual([
      "Saved role shortcuts",
      "Up to 2 shortcuts",
      "Up to 8 shortcuts",
    ]);
  });
  it("includes every compared feature in both card lists", () => {
    const labels = PLAN_COMPARISON_ROWS.map(([label]) => label);
    expect(new Set(labels).size).toBe(labels.length);
    expect(labels).toEqual(
      expect.arrayContaining([
        "Monthly emails",
        "Emails per UTC day",
        "Recipients per campaign",
        "Saved templates",
        "PDF attachment",
        "Gmail acceptance status",
        "CSV import",
        "Contact job roles",
        "Edit recipient roles in Compose",
        "Saved role shortcuts",
        "Re-add previously emailed contacts",
        "Manual repeat sends",
        "Mark replied button",
        "Follow-up reminders",
        "Themes",
        "Preview highlight colors",
        "Priority support",
      ]),
    );
    for (const plan of ["FREE", "PAID"] as const) {
      expect(PLAN_CARD_FEATURES[plan].map((feature) => feature.label)).toEqual(
        labels,
      );
      for (const label of [
        "PDF attachment",
        "Gmail acceptance status",
        "CSV import",
        "Preview highlight colors",
        "Priority support",
      ])
        expect(PLAN_FEATURES[plan].some((text) => text.startsWith(label))).toBe(
          true,
        );
    }
  });
  it("includes re-adding contacts and metered manual repeats on both plans", () => {
    expect(PLAN_COMPARISON_ROWS).toContainEqual([
      "Re-add previously emailed contacts",
      "Enter and save details in Contacts",
      "Enter and save details in Contacts",
    ]);
    expect(PLAN_COMPARISON_ROWS).toContainEqual([
      "Add to shortlist directly from History",
      "Unavailable",
      "Included",
    ]);
    expect(PLAN_COMPARISON_ROWS).toContainEqual([
      "Manual repeat sends",
      "Included; count toward allowances",
      "Included; count toward allowances",
    ]);
  });
  it("marks unavailable Free capabilities instead of showing included checks", () => {
    expect(
      PLAN_CARD_FEATURES.FREE.find((feature) => feature.label === "CSV import"),
    ).toMatchObject({ included: false, text: "CSV import: Unavailable" });
    expect(PLAN_CARD_FEATURES.PAID.every((feature) => feature.included)).toBe(
      true,
    );
  });
});
